function initBattle(){const left=qs('#battleLeft');if(!left)return;const foods=allFoods();const opts=foods.map((x,i)=>`<option value="${i}">${esc(x.name)}</option>`).join('');left.innerHTML=opts;qs('#battleRight').innerHTML=opts;qs('#battleRight').value=Math.min(1,foods.length-1);let metric='calories';qsa('[data-battle-metric]').forEach(b=>b.onclick=()=>{metric=b.dataset.battleMetric;qsa('[data-battle-metric]').forEach(x=>x.classList.toggle('active',x===b));render()});left.onchange=render;qs('#battleRight').onchange=render;function render(){const a=foods[+left.value],b=foods[+qs('#battleRight').value],na=estimatedNutrition(a),nb=estimatedNutrition(b);const higherBetter=['protein','fiber'].includes(metric),va=na[metric],vb=nb[metric];const winner=va===vb?null:(higherBetter?(va>vb?a:b):(va<vb?a:b));qs('#battleArena').innerHTML=[a,b].map((x,i)=>{const n=i?nb:na;return `<article class="fighter"><img src="${photoFor(x)}" alt="${esc(x.name)}"><div class="fighter-body"><div class="section-kicker">FIGHTER ${i+1}</div><h2>${esc(x.name)}</h2><div class="mini-macros">${miniMacros(n)}</div></div></article>`}).join('');qs('#battleWinner').innerHTML=winner?`<span class="crown">👑</span><div class="section-kicker">WINNER · ${metric.toUpperCase()} ${higherBetter?'HIGHER':'LOWER'} WINS</div><strong>${esc(winner.name)}</strong>`:`<span class="crown">🤝</span><strong>IT'S A TIE</strong>`}render()}
function dailySeed(){const d=new Date();return d.getFullYear()*372+(d.getMonth()+1)*31+d.getDate()}
function moveFacts(m){return [`${m.name} uses a preset MET estimate so burn updates automatically from duration and profile weight.`,`The movement log keeps estimated burn separate from the 2,100–2,150 kcal maintenance reference.`,m.note||'This preset is part of the recovered CCD movement list.']}
